def vae_loss(x):
    z, mu, logvar = encode(x)
    xhat = decode(z)
    rec = mse(x, xhat)
    kl = -0.5 * mean(1 + logvar - mu**2 - logvar.exp())
    return rec + beta * kl + perc(x, xhat) + adv(xhat)

def fm_train(x1):
    x0 = randn_like(x1)
    t = rand()
    xt = (1 - t) * x0 + t * x1
    v = x1 - x0
    return mse(v, net(xt, t))

