def propagate(feats, keyframes, edited):
    for f in non_keyframes:
        for i, t in enumerate(feats[f]):
            k = nearest_keyframe(t, keyframes)
            feats[f][i] = edited[k][match(t, feats[k])]
    return feats

def cd_loss(x, t_n, t_next):
    x_next = x + teacher_ode_step(x, t_next, t_n)
    pred_next = f_student(x_next, t_next)
