def fvd(real, gen):
    fr = i3d(real).reshape(-1, d)
    fg = i3d(gen).reshape(-1, d)
    mr, sr = mean(fr), cov(fr)
    mg, sg = mean(fg), cov(fg)
    return ||mr-mg||**2 + trace(sr + sg - 2*sqrtm(sr @ sg))

def vbench(model, prompts):
    scores = {d: [] for d in DIMENSIONS}
    for p in prompts:
        v = model.generate(p)
        for d in DIMENSIONS:
            scores[d].append(evaluator[d](v, p))
    q = mean(scores[d] for d in QUALITY)
    s = mean(scores[d] for d in SEMANTIC)
    return (q + s) / 2, scores

def sliding_window(history, new_block):
    window = history[-K:]
    memory = compress(history[:-K])
    ctx = concat(window, memory)
    return denoise(new_block, ctx)
